package com.suriya.expensetracker;

import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.graphics.Color;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import java.text.SimpleDateFormat;
import java.util.*;

/** Local EMI schedules and user-confirmed payments. */
final class EmiPage {
    final MainActivity a;final Store store;
    EmiPage(MainActivity activity,Store database){a=activity;store=database;}
    static final class Plan {long id,amount,start;int months;String product;}
    static final class Payment {long id;Long expense;}
    String date(long ms){return new SimpleDateFormat("dd MMM yyyy",Locale.ENGLISH).format(new Date(ms));}
    ArrayList<Plan> plans(){ArrayList<Plan> result=new ArrayList<>();try(Cursor c=store.getReadableDatabase().rawQuery("SELECT _id,product,amount,start_date,months FROM emi_plans ORDER BY _id DESC",null)){while(c.moveToNext()){Plan p=new Plan();p.id=c.getLong(0);p.product=c.getString(1);p.amount=c.getLong(2);p.start=c.getLong(3);p.months=c.getInt(4);result.add(p);}}return result;}
    HashMap<Integer,Payment> payments(long id){HashMap<Integer,Payment> map=new HashMap<>();try(Cursor c=store.getReadableDatabase().rawQuery("SELECT _id,installment,expense_id FROM emi_payments WHERE plan_id=?",new String[]{""+id})){while(c.moveToNext()){Payment p=new Payment();p.id=c.getLong(0);p.expense=c.isNull(2)?null:c.getLong(2);map.put(c.getInt(1),p);}}return map;}
    void render(){
        a.showingHome=true;a.showingPayees=false;a.trackerPage=false;a.fuelPage=false;a.emiPage=true;a.updateSystemBack();a.root=a.column();a.root.setBackgroundColor(a.bg(0xfff6f7fb));a.root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});a.setContentView(a.root);
        LinearLayout content=a.column();content.setPadding(a.dp(20),a.dp(18),a.dp(20),0);a.root.addView(content,new LinearLayout.LayoutParams(-1,0,1));content.addView(a.text("YOUR PAYMENTS",11,0xff7f8ba1));a.space(content,4);content.addView(a.bold("EMI tracker",24,0xff182137));a.space(content,5);content.addView(a.text("Keep track of upcoming and paid instalments",13,0xff8490a4));a.space(content,16);
        TextView add=a.accentAction("+ Add EMI",0xffb69af5);content.addView(add,new LinearLayout.LayoutParams(-1,a.dp(50)));add.setOnClickListener(v->editPlan(null));a.space(content,14);
        ScrollView scroll=new ScrollView(a);content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));a.list=a.column();scroll.addView(a.list);
        ArrayList<Plan> plans=plans();if(plans.isEmpty()){LinearLayout empty=a.card(Color.WHITE,20);empty.addView(a.bold("No EMI plans yet",16,0xff27334a));a.space(empty,6);empty.addView(a.text("Add a product and its monthly payment to get started.",13,0xff8490a4));a.list.addView(empty);}
        long today=EmiSchedule.day(System.currentTimeMillis());
        for(Plan p:plans){HashMap<Integer,Payment> paid=payments(p.id);int next=-1;for(int i=0;i<p.months;i++)if(!paid.containsKey(i)){next=i;break;}
            LinearLayout card=a.card(Color.WHITE,16);LinearLayout heading=new LinearLayout(a);heading.setGravity(Gravity.CENTER_VERTICAL);heading.addView(a.bold(p.product,16,0xff202b40),new LinearLayout.LayoutParams(0,-2,1));heading.addView(a.accentText(a.money(p.amount),16,0xffb69af5,true));card.addView(heading);a.space(card,6);card.addView(a.text(paid.size()+" of "+p.months+" instalments paid  •  "+a.money(p.amount)+" / month",12,0xff8490a4));a.space(card,6);
            ProgressBar progress=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(p.months);progress.setProgress(paid.size());progress.setProgressTintList(android.content.res.ColorStateList.valueOf(0xffb69af5));progress.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff484848));card.addView(progress,new LinearLayout.LayoutParams(-1,a.dp(5)));a.space(card,9);
            long due=next<0?0:EmiSchedule.due(p.start,next);int statusColor=next<0?0xff70dba8:EmiSchedule.day(due)<today?0xffff858c:0xffb69af5;card.addView(a.accentText(next<0?"All instalments marked paid":(EmiSchedule.day(due)<today?"Overdue since ":"Next unpaid: ")+date(due),13,statusColor,false));a.space(card,10);
            TextView view=a.secondaryAction("View schedule  →");card.addView(view);view.setOnClickListener(v->schedule(p));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=a.dp(10);a.list.addView(card,lp);
        }a.addNavigation(false);
    }
    void editPlan(Plan existing){
        LinearLayout form=a.column();form.setPadding(a.dp(22),a.dp(4),a.dp(22),a.dp(8));form.addView(a.formLabel("PRODUCT NAME"));EditText name=new EditText(a);name.setHint("e.g. Laptop");a.styleField(name);if(existing!=null)name.setText(existing.product);form.addView(name);a.space(form,10);
        form.addView(a.formLabel("MONTHLY EMI  ·  ₹"));EditText amount=new EditText(a);amount.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);amount.setHint("0.00");a.styleField(amount);if(existing!=null)amount.setText(a.amt(existing.amount));form.addView(amount);a.space(form,10);
        form.addView(a.formLabel("FIRST EMI DATE"));Calendar chosen=Calendar.getInstance();chosen.setTimeInMillis(existing==null?System.currentTimeMillis():existing.start);chosen.set(Calendar.HOUR_OF_DAY,12);chosen.set(Calendar.MINUTE,0);chosen.set(Calendar.SECOND,0);chosen.set(Calendar.MILLISECOND,0);TextView dateButton=a.action(date(chosen.getTimeInMillis())+"  ▾",0xffefedff,0xff534acb);form.addView(dateButton);dateButton.setOnClickListener(v->a.showStyled(new DatePickerDialog(a,(view,y,m,d)->{chosen.set(y,m,d);dateButton.setText(date(chosen.getTimeInMillis())+"  ▾");},chosen.get(Calendar.YEAR),chosen.get(Calendar.MONTH),chosen.get(Calendar.DAY_OF_MONTH))));a.space(form,10);
        form.addView(a.formLabel("TENURE  ·  MONTHS"));EditText months=new EditText(a);months.setInputType(InputType.TYPE_CLASS_NUMBER);months.setHint("e.g. 12");a.styleField(months);if(existing!=null)months.setText(""+existing.months);form.addView(months);a.space(form,8);form.addView(a.text("Reminders appear when you open the app from two days before each unpaid EMI.",12,0xff7b879d));
        ScrollView scroll=new ScrollView(a);scroll.addView(form);AlertDialog d=new AlertDialog.Builder(a).setTitle(existing==null?"Add EMI plan":"Edit EMI plan").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();
        d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{try{String product=name.getText().toString().trim();long value=a.parseAmount(amount.getText().toString());int term=Integer.parseInt(months.getText().toString().trim());if(product.isEmpty()||value<=0||term<1||term>360)throw new IllegalArgumentException();ContentValues cv=new ContentValues();cv.put("product",product);cv.put("amount",value);cv.put("start_date",chosen.getTimeInMillis());cv.put("months",term);SQLiteDatabase db=store.getWritableDatabase();if(existing==null)db.insertOrThrow("emi_plans",null,cv);else if(db.update("emi_plans",cv,"_id=?",new String[]{""+existing.id})!=1)throw new IllegalStateException();d.dismiss();render();}catch(Exception e){Toast.makeText(a,"Enter a product, a valid amount and a tenure of 1–360 months.",Toast.LENGTH_LONG).show();}}));a.showStyled(d);
    }
    void schedule(Plan p){
        final AlertDialog[] scheduleDialog={null};HashMap<Integer,Payment> paid=payments(p.id);LinearLayout body=a.column();body.setPadding(a.dp(20),a.dp(4),a.dp(20),a.dp(8));body.addView(a.text(a.money(p.amount)+" per month  •  "+paid.size()+" / "+p.months+" paid",13,0xff78859a));a.space(body,12);
        long today=EmiSchedule.day(System.currentTimeMillis());for(int i=0;i<p.months;i++){final int installment=i;long due=EmiSchedule.due(p.start,i);Payment payment=paid.get(i);boolean isPaid=payment!=null;LinearLayout row=a.card(0xfff3f4fa,12);LinearLayout head=new LinearLayout(a);head.setGravity(Gravity.CENTER_VERTICAL);head.addView(a.bold("#"+(i+1)+"  ·  "+date(due),14,0xff202b40),new LinearLayout.LayoutParams(0,-2,1));head.addView(a.bold(isPaid?"Paid":EmiSchedule.day(due)<today?"Overdue":"Pending",12,isPaid?0xff12886b:EmiSchedule.day(due)<today?0xffb64c60:0xff78859a));row.addView(head);a.space(row,7);row.addView(a.text(isPaid?(payment.expense==null?"Paid • not linked to Tracker":"Paid • linked to Tracker"):"Tap to mark this instalment paid",12,0xff78859a));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=a.dp(8);body.addView(row,lp);row.setOnClickListener(v->{scheduleDialog[0].dismiss();if(isPaid)undoPayment(p,payment);else askPayment(p,installment,due);});}
        ScrollView scroll=new ScrollView(a);scroll.addView(body);AlertDialog.Builder b=new AlertDialog.Builder(a).setTitle(p.product+" • EMI schedule").setView(scroll).setPositiveButton("Close",null).setNeutralButton("Manage",null);AlertDialog d=b.create();scheduleDialog[0]=d;d.setOnShowListener(x->d.getButton(-3).setOnClickListener(v->{d.dismiss();manage(p);}));a.showStyled(d);
    }
    void manage(Plan p){String[] items={"Edit plan", "Delete plan"};a.showStyled(new AlertDialog.Builder(a).setTitle("Manage "+p.product).setItems(items,(d,which)->{if(which==0){if(!payments(p.id).isEmpty()){a.showStyled(new AlertDialog.Builder(a).setTitle("Payments already recorded").setMessage("Undo recorded payments before changing the EMI schedule.").setPositiveButton("OK",null));}else editPlan(p);}else a.showStyled(new AlertDialog.Builder(a).setTitle("Delete EMI plan?").setMessage("The plan and its payment marks will be removed. Linked Tracker transactions will remain.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(dd,w)->{SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{db.delete("emi_payments","plan_id=?",new String[]{""+p.id});db.delete("emi_plans","_id=?",new String[]{""+p.id});db.setTransactionSuccessful();}finally{db.endTransaction();}render();}));}).setNegativeButton("Cancel",null));}
    void askPayment(Plan plan,int index,long due){a.showStyled(new AlertDialog.Builder(a).setTitle("Mark EMI paid?").setMessage(""+plan.product+" • "+date(due)+"\nLink an existing debit from Tracker?").setNeutralButton("Cancel",(d,w)->schedule(plan)).setNegativeButton("No",(d,w)->record(plan,index,0)).setPositiveButton("Yes",(d,w)->chooseTransaction(plan,index)).create());}
    void chooseTransaction(Plan plan,int index){
        ArrayList<Long> ids=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();try(Cursor c=store.getReadableDatabase().rawQuery("SELECT t._id,t.title,t.date,t.amount FROM transactions t WHERE t.kind='Expense' AND NOT EXISTS (SELECT 1 FROM emi_payments e WHERE e.expense_id=t._id) ORDER BY t.date DESC,t._id DESC",null)){while(c.moveToNext()){ids.add(c.getLong(0));labels.add(c.getString(1)+"  •  "+date(c.getLong(2))+"\n"+a.money(c.getLong(3)));}}
        if(ids.isEmpty()){a.showStyled(new AlertDialog.Builder(a).setTitle("No available debits").setMessage("Add or import a transaction in Tracker, then try again. The EMI is still pending.").setPositiveButton("OK",(d,w)->schedule(plan)));return;}
        LinearLayout body=a.column();body.setPadding(a.dp(20),a.dp(4),a.dp(20),a.dp(4));EditText search=new EditText(a);search.setHint("Search by payee, date or amount");a.styleField(search);body.addView(search);a.space(body,10);ScrollView scroll=new ScrollView(a);LinearLayout rows=a.column();scroll.addView(rows);body.addView(scroll,new LinearLayout.LayoutParams(-1,a.dp(320)));AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Choose a Tracker debit").setView(body).setNegativeButton("Cancel",(d,w)->schedule(plan)).create();
        Runnable update=()->{rows.removeAllViews();String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);for(int i=0;i<ids.size();i++){if(!labels.get(i).toLowerCase(Locale.ROOT).contains(q))continue;long id=ids.get(i);TextView item=a.action(labels.get(i),0xfff3f4fa,0xff202b40);item.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=a.dp(7);rows.addView(item,lp);item.setOnClickListener(v->{dialog.dismiss();record(plan,index,id);});}if(rows.getChildCount()==0)rows.addView(a.text("No matching debits.",13,0xff78859a));};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){update.run();}public void afterTextChanged(android.text.Editable e){}});update.run();body.setFocusableInTouchMode(true);body.requestFocus();a.showStyled(dialog);if(dialog.getWindow()!=null)dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);
    }
    void record(Plan plan,int index,long expense){SQLiteDatabase db=store.getWritableDatabase();try{db.beginTransaction();try(Cursor p=db.rawQuery("SELECT months FROM emi_plans WHERE _id=?",new String[]{""+plan.id})){if(!p.moveToFirst()||index<0||index>=p.getInt(0))throw new IllegalStateException();}if(expense!=0){try(Cursor c=db.rawQuery("SELECT _id FROM transactions WHERE _id=? AND kind='Expense' AND NOT EXISTS (SELECT 1 FROM emi_payments WHERE expense_id=?)",new String[]{""+expense,""+expense})){if(!c.moveToFirst())throw new IllegalStateException();}}ContentValues cv=new ContentValues();cv.put("plan_id",plan.id);cv.put("installment",index);cv.put("paid_at",System.currentTimeMillis());if(expense!=0)cv.put("expense_id",expense);db.insertOrThrow("emi_payments",null,cv);db.setTransactionSuccessful();}catch(Exception e){Toast.makeText(a,"Could not record payment. Check the transaction and try again.",Toast.LENGTH_LONG).show();return;}finally{if(db.inTransaction())db.endTransaction();}render();Toast.makeText(a,expense==0?"EMI marked paid without Tracker link":"EMI marked paid and linked",Toast.LENGTH_LONG).show();}
    void undoPayment(Plan plan,Payment payment){a.showStyled(new AlertDialog.Builder(a).setTitle("Undo payment mark?").setMessage("The instalment will become pending again. Any linked Tracker transaction will remain.").setNegativeButton("Cancel",(d,w)->schedule(plan)).setPositiveButton("Undo",(d,w)->{store.getWritableDatabase().delete("emi_payments","_id=?",new String[]{""+payment.id});render();}).create());}
    void showReminders(){if(a.isFinishing()||a.isDestroyed())return;long today=EmiSchedule.day(System.currentTimeMillis());ArrayList<String> lines=new ArrayList<>();int count=0;for(Plan p:plans()){HashMap<Integer,Payment> paid=payments(p.id);for(int i=0;i<p.months;i++){long due=EmiSchedule.due(p.start,i);if(EmiSchedule.reminderStart(due)>today)break;if(paid.containsKey(i))continue;count++;if(lines.size()<5)lines.add(p.product+"  •  "+a.money(p.amount)+"\n"+(EmiSchedule.day(due)<today?"Overdue since ":"Due ")+date(due));}}if(count==0)return;String message=android.text.TextUtils.join("\n\n",lines)+(count>5?"\n\nAnd "+(count-5)+" more unpaid instalments.":"");a.showStyled(new AlertDialog.Builder(a).setTitle("EMI reminders").setMessage(message).setNegativeButton("Later",null).setPositiveButton("View EMIs",(d,w)->render()));}
}
